  "implementation": "def solve(case):
    nodes = case["nodes"]
    core = case["core_distance"]
    dists = case["distances"]
    edges = []
    for a, b, d in dists:
        w = max(core[a], core[b], d)
        if a <= b:
            edges.append((a, b, w))
        else:
            edges.append((b, a, w))
    edges.sort(key=lambda e: (e[2], e[0], e[1]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for a, b, w in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
}
